from pathlib import Path
import json,subprocess,os,hashlib,datetime,sys
root=Path.cwd();folder=root/'target/perf-win-2026-11-09';dest=folder/'neon-probe'
sys.path.insert(0,str(root/'benchmarks/iteration/unity/features'))
import project,monitor
record=json.loads((folder/'native-build.json').read_text())
before=folder/'ecs-39b51adede901aa9f80dc19398a9accd5d8f5c1b3ae5ca1d7a01315bc9451c82';after=Path(record['executable'])
report={'candidate_build':record,'before_sha256':hashlib.sha256(before.read_bytes()).hexdigest(),'scope':'native exact NEON transpose/sqrt fixture, not production FPS','results':[]}
for round_ in range(2):
 cases=[('w1',1,4096,120),('w1',14,4096,120),('w3',1,8192,3000),('w3',14,8192,3000)]
 for workload,threads,batch,warmup in (cases if round_==0 else reversed(cases)):
  for mode,exe in ([('before',before),('after',after)] if round_==0 else [('after',after),('before',before)]):
   name=f'r{round_}-{workload}-t{threads}-{mode}';output=dest/(name+'.json');a=project.resources(strict=False)
   if a['busy_tools']:raise RuntimeError(a)
   command=['/usr/bin/nice','-n','10',str(exe),workload,'1000000',str(threads),str(warmup),'300','simd',str(batch),str(output)]
   observed=[]
   with (dest/(name+'.stdout')).open('w') as out,(dest/(name+'.stderr')).open('w') as err:
    child=subprocess.Popen(command,stdout=out,stderr=err)
    while child.poll() is None:
     try:child.wait(timeout=1)
     except subprocess.TimeoutExpired:observed.append(project.resources(strict=False))
    status=child.wait()
   z=project.resources(strict=False)
   entry={'name':name,'command':command,'before':a,'observations':observed,'after':z,'exit_code':status,'accepted':not any(x['busy_tools'] for x in [a,*observed,z]) and monitor.power_stable(a,observed,z),'result':json.loads(output.read_text()) if status==0 else None}
   report['results'].append(entry);(dest/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(name,status,entry['accepted'],None if entry['result'] is None else [entry['result']['p50_ms'],entry['result']['p95_ms']],flush=True)
   if status or not entry['accepted']:raise RuntimeError(name)
for w in ['w1','w3']:
 assert len({r['result']['state_hash'] for r in report['results'] if r['result']['workload']==w})==1
report['complete']=True;(dest/'report.json').write_text(json.dumps(report,indent=2)+'\n')
